import bisect

def table_zone_eval(zone, ops):
    # ---------- validate zone ----------
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("invalid zone")

    initial, transitions = zone
    if not isinstance(initial, int) or isinstance(initial, bool):
        raise ValueError("invalid initial")
    if abs(initial) > 50400:
        raise ValueError("initial out of range")

    if not isinstance(transitions, (list, tuple)):
        raise ValueError("invalid transitions")
    if len(transitions) > 100000:
        raise ValueError("too many transitions")

    T_list = []
    off_list = [initial]
    prev_t = None
    prev_off = initial

    for entry in transitions:
        if not isinstance(entry, (list, tuple)) or len(entry) != 2:
            raise ValueError("invalid transition entry")
        t, off = entry
        if not isinstance(t, int) or isinstance(t, bool):
            raise ValueError("invalid transition t")
        if not isinstance(off, int) or isinstance(off, bool):
            raise ValueError("invalid transition off")
        if abs(t) > 10**13 or abs(off) > 50400:
            raise ValueError("transition value out of range")
        if prev_t is not None and t <= prev_t + 172800:
            raise ValueError("transitions too close")
        if abs(off - prev_off) > 86400:
            raise ValueError("offset change too large")

        T_list.append(t)
        off_list.append(off)
        prev_t = t
        prev_off = off

    n = len(T_list)
    T_list = tuple(T_list)
    off_list = tuple(off_list)

    # L[i] = beginning wall time of interval i, for i >= 1
    # R[i] = end wall time of interval i, for i <= n-1
    L_list = tuple(T_list[i] + off_list[i + 1] for i in range(n))
    R_list = tuple(T_list[i] + off_list[i] for i in range(n))

    # ---------- helpers ----------
    def resolve(w, fold):
        if not isinstance(w, int) or isinstance(w, bool):
            raise ValueError("invalid w")
        if not isinstance(fold, int) or isinstance(fold, bool):
            raise ValueError("invalid fold")
        if fold != 0 and fold != 1:
            raise ValueError("fold must be 0 or 1")
        if abs(w) > 10**13:
            raise ValueError("w out of range")

        # Last interval whose left endpoint is <= w.
        k = bisect.bisect_right(L_list, w)
        # First interval whose right endpoint is > w.
        m = bisect.bisect_right(R_list, w)

        candidates = []
        if m <= k:
            for i in range(m, k + 1):
                candidates.append(w - off_list[i])

        if not candidates:
            # Gap: between interval k and interval k+1.
            j = k + 1
            a = off_list[j - 1]
            b = off_list[j]
            return w - a if fold == 0 else w - b

        if len(candidates) == 1:
            return candidates[0]

        candidates.sort()
        return candidates[0] if fold == 0 else candidates[-1]

    def get_wall(x):
        if not isinstance(x, int) or isinstance(x, bool):
            raise ValueError("invalid x")
        if abs(x) > 10**13:
            raise ValueError("x out of range")

        j = bisect.bisect_right(T_list, x)  # offset index
        off = off_list[j]
        w = x + off

        f = 0
        if j > 0 and off_list[j] < off_list[j - 1]:
            # Possible repeated wall time after a fall-back transition.
            delta = off_list[j - 1] - off_list[j]
            if x < T_list[j - 1] + delta:
                f = 1

        return (w, f)

    # ---------- validate and run ops ----------
    results = []

    for op in ops:
        if not isinstance(op, (list, tuple)) or len(op) < 1:
            raise ValueError("invalid operation")
        name = op[0]
        if not isinstance(name, str):
            raise ValueError("invalid operation name")

        if name == "instant":
            if len(op) != 3:
                raise ValueError("instant needs 3 items")
            w, fold = op[1], op[2]
            results.append(resolve(w, fold))

        elif name == "wall":
            if len(op) != 2:
                raise ValueError("wall needs 2 items")
            x = op[1]
            results.append(get_wall(x))

        elif name == "add":
            if len(op) != 5:
                raise ValueError("add needs 5 items")
            w, fold, days, secs = op[1], op[2], op[3], op[4]

            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("invalid w")
            if not isinstance(fold, int) or isinstance(fold, bool):
                raise ValueError("invalid fold")
            if fold != 0 and fold != 1:
                raise ValueError("fold must be 0 or 1")
            if not isinstance(days, int) or isinstance(days, bool):
                raise ValueError("invalid days")
            if not isinstance(secs, int) or isinstance(secs, bool):
                raise ValueError("invalid secs")
            if abs(w) > 10**13 or abs(secs) > 10**13 or abs(days) > 10**6:
                raise ValueError("add value out of range")

            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs
            results.append(get_wall(x2))

        else:
            raise ValueError("unknown operation")

    return results

