import heapq


def gate_trace(gates, stimuli, watch, until):
    # ---------- validation ----------
    if not isinstance(gates, (list, tuple)):
        raise ValueError("gates must be a list or tuple")
    if len(gates) > 60:
        raise ValueError("Too many gates")

    valid_ops = {"AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"}
    all_signals = set()
    out_names = set()
    gate_map = {}

    for g in gates:
        if not isinstance(g, tuple) or len(g) != 4:
            raise ValueError("Each gate must be a tuple (out, op, ins, delay)")
        out, op, ins, delay = g

        if not isinstance(out, str) or out == "":
            raise ValueError("Gate output must be a non-empty string")
        if out in out_names:
            raise ValueError("Duplicate gate output")
        if not isinstance(op, str) or op not in valid_ops:
            raise ValueError("Invalid gate operation")
        if not isinstance(ins, (list, tuple)):
            raise ValueError("Gate inputs must be a list or tuple")
        if op in ("NOT", "BUF") and len(ins) != 1:
            raise ValueError(f"{op} gate requires exactly 1 input")
        if op in ("AND", "OR", "XOR", "NAND", "NOR") and not (2 <= len(ins) <= 4):
            raise ValueError(f"{op} gate requires 2 to 4 inputs")
        for inp in ins:
            if not isinstance(inp, str) or inp == "":
                raise ValueError("Gate input must be a non-empty string")
        if not isinstance(delay, int) or isinstance(delay, bool) or not (0 <= delay <= 10**12):
            raise ValueError("Gate delay must be an integer 0..10**12")

        out_names.add(out)
        all_signals.add(out)
        gate_map[out] = {"op": op, "ins": list(ins), "delay": delay}
        for inp in ins:
            all_signals.add(inp)

    if not isinstance(stimuli, (list, tuple)):
        raise ValueError("stimuli must be a list or tuple")
    if len(stimuli) > 200:
        raise ValueError("Too many stimuli")

    for s in stimuli:
        if not isinstance(s, tuple) or len(s) != 3:
            raise ValueError("Each stimulus must be a tuple (time, signal, value)")
        time, signal, value = s
        if not isinstance(time, int) or isinstance(time, bool) or not (0 <= time <= 10**12):
            raise ValueError("Stimulus time must be an integer 0..10**12")
        if not isinstance(signal, str) or signal == "":
            raise ValueError("Stimulus signal must be a non-empty string")
        if not isinstance(value, int) or isinstance(value, bool) or value not in (0, 1):
            raise ValueError("Stimulus value must be 0 or 1")

    if not isinstance(watch, (list, tuple)):
        raise ValueError("watch must be a list or tuple")
    for w in watch:
        if not isinstance(w, str) or w == "":
            raise ValueError("Watch names must be non-empty strings")

    if not isinstance(until, int) or isinstance(until, bool) or not (0 <= until <= 10**12):
        raise ValueError("until must be an integer 0..10**12")

    # ---------- cycle check ----------
    graph = {s: [] for s in all_signals}
    for out, op, ins, delay in gates:
        for inp in ins:
            graph[inp].append(out)

    color = {s: 0 for s in all_signals}
    has_cycle = False

    def dfs(u):
        nonlocal has_cycle
        if has_cycle:
            return
        color[u] = 1
        for v in graph[u]:
            if color[v] == 1:
                has_cycle = True
                return
            if color[v] == 0:
                dfs(v)
        color[u] = 2

    for s in all_signals:
        if color[s] == 0:
            dfs(s)
            if has_cycle:
                raise ValueError("Cycle detected in gate graph")

    primary_inputs = all_signals - out_names

    for _, signal, _ in stimuli:
        if signal not in primary_inputs:
            raise ValueError(f"Stimulus signal '{signal}' is not a primary input")

    for w in watch:
        if w not in all_signals:
            raise ValueError(f"Watch name '{w}' is not a known signal")

    # ---------- helpers ----------
    def evaluate(op, vals):
        if op == "AND":
            return 1 if all(vals) else 0
        if op == "OR":
            return 1 if any(vals) else 0
        if op == "XOR":
            return 1 if sum(vals) % 2 else 0
        if op == "NAND":
            return 0 if all(vals) else 1
        if op == "NOR":
            return 0 if any(vals) else 1
        if op == "NOT":
            return 1 - vals[0]
        if op == "BUF":
            return vals[0]
        return 0

    # ---------- simulation state ----------
    signal_values = {s: 0 for s in all_signals}
    pending = {}  # out -> (due_time, value)

    stimuli_by_time = {}
    for time, signal, value in stimuli:
        stimuli_by_time.setdefault(time, []).append((signal, value))

    event_heap = [0]
    for t in stimuli_by_time:
        if t <= until:
            event_heap.append(t)
    heapq.heapify(event_heap)
    processed = set()

    trace = {w: [] for w in watch}
    last_values = {w: 0 for w in watch}

    def apply_batch(t, first_round):
        """Apply stimuli and/or pending assignments due at t. Return changed set."""
        affected = set()

        # collect affected before changing values
        if first_round and t in stimuli_by_time:
            for signal, _ in stimuli_by_time[t]:
                affected.add(signal)

        due_assignments = []
        if pending:
            due_assignments = [(out, val) for out, (due, val) in pending.items() if due == t]
        for out, _ in due_assignments:
            affected.add(out)

        before = {s: signal_values[s] for s in affected}

        # stimuli first, in list order
        if first_round and t in stimuli_by_time:
            for signal, value in stimuli_by_time[t]:
                signal_values[signal] = value

        # then pending assignments due at t
        for out, val in due_assignments:
            signal_values[out] = val
            del pending[out]

        changed = set()
        for s in affected:
            if signal_values[s] != before[s]:
                changed.add(s)
        return changed

    def run_evaluation(t, changed, all_gates):
        """Evaluate gates, update pending, push future events."""
        for out_name, info in gate_map.items():
            if not all_gates and not any(inp in changed for inp in info["ins"]):
                continue

            vals = [signal_values[inp] for inp in info["ins"]]
            new_val = evaluate(info["op"], vals)
            current_val = signal_values[out_name]

            # delete own pending assignment
            if out_name in pending:
                del pending[out_name]

            if new_val != current_val:
                due_time = t + info["delay"]
                pending[out_name] = (due_time, new_val)
                if due_time <= until and due_time > t:
                    heapq.heappush(event_heap, due_time)

    # ---------- main event loop ----------
    while event_heap:
        t = heapq.heappop(event_heap)
        if t > until:
            break
        if t in processed:
            continue
        processed.add(t)

        # Round 1
        changed = apply_batch(t, first_round=True)
        run_evaluation(t, changed, all_gates=(t == 0))

        # Delta rounds with delay 0
        while any(due == t for _, (due, _) in pending.items()):
            changed = apply_batch(t, first_round=False)
            run_evaluation(t, changed, all_gates=False)

        # Record trace after final value of this instant
        for w in watch:
            v = signal_values[w]
            if v != last_values[w]:
                trace[w].append((t, v))
                last_values[w] = v

    return trace

import sys
sys.setrecursionlimit(10000)

class Type: pass

class TVar(Type):
    def __init__(self, idx): self.idx = idx
    def __eq__(self, o): return isinstance(o, TVar) and self.idx == o.idx
    def __hash__(self): return hash(self.idx)

class TInt(Type): pass
class TBool(Type): pass
class TString(Type): pass
class TUnit(Type): pass

class TList(Type):
    def __init__(self, e): self.e = e
    def __eq__(self, o): return isinstance(o, TList) and self.e == o.e
    def __hash__(self): return hash(('L', self.e))

class TRef(Type):
    def __init__(self, e): self.e = e
    def __eq__(self, o): return isinstance(o, TRef) and self.e == o.e
    def __hash__(self): return hash(('R', self.e))

class TArrow(Type):
    def __init__(self, args, ret): self.args = args; self.ret = ret
    def __eq__(self, o): return isinstance(o, TArrow) and self.args == o.args and self.ret == o.ret
    def __hash__(self): return hash(('A', self.args, self.ret))

class TScheme:
    def __init__(self, tvs, t): self.tvs = set(tvs); self.t = t

_fresh = 0
def fresh():
    global _fresh
    t = TVar(_fresh); _fresh += 1; return t

def apply_subst(t, s):
    if isinstance(t, TVar):
        if t in s:
            return apply_subst(s[t], s)
        return t
    if isinstance(t, TList): return TList(apply_subst(t.e, s))
    if isinstance(t, TRef): return TRef(apply_subst(t.e, s))
    if isinstance(t, TArrow):
        return TArrow(tuple(apply_subst(a, s) for a in t.args), apply_subst(t.ret, s))
    return t

def occurs(v, t, s):
    t = apply_subst(t, s)
    if isinstance(t, TVar):
        return t == v
    if isinstance(t, TList): return occurs(v, t.e, s)
    if isinstance(t, TRef): return occurs(v, t.e, s)
    if isinstance(t, TArrow):
        return any(occurs(v, a, s) for a in t.args) or occurs(v, t.ret, s)
    return False

def unify(t1, t2, s):
    t1 = apply_subst(t1, s)
    t2 = apply_subst(t2, s)
    if t1 == t2: return s
    if isinstance(t1, TVar):
