    def __init__(self, e):
        self.e = e

    def __eq__(self, o):
        return isinstance(o, TRef) and self.e == o.e

    def __hash__(self):
        return hash(('R', self.e))


class TArrow(Type):
    __slots__ = ('args', 'ret')

    def __init__(self, args, ret):
        self.args = tuple(args)
        self.ret = ret

    def __eq__(self, o):
        return (isinstance(o, TArrow) and self.args == o.args
                and self.ret == o.ret)

    def __hash__(self):
        return hash(('A', self.args, self.ret))


class TScheme:
    __slots__ = ('tvs', 't')

    def __init__(self, tvs, t):
        self.tvs = set(tvs)
        self.t = t


_fresh = 0


def fresh():
    global _fresh
    t = TVar(_fresh)
    _fresh += 1
    return t


def apply_subst(t, s):
    if isinstance(t, TVar):
        if t in s:
            return apply_subst(s[t], s)
        return t
    if isinstance(t, TList):
        return TList(apply_subst(t.e, s))
    if isinstance(t, TRef):
        return TRef(apply_subst(t.e, s))
    if isinstance(t, TArrow):
        return TArrow(tuple(apply_subst(a, s) for a in t.args),
                      apply_subst(t.ret, s))
    return t


def occurs(v, t, s):
    t = apply_subst(t, s)
    if isinstance(t, TVar):
        return t == v
    if isinstance(t, TList):
        return occurs(v, t.e, s)
    if isinstance(t, TRef):
        return occurs(v, t.e, s)
    if isinstance(t, TArrow):
        return any(occurs(v, a, s) for a in t.args) or occurs(v, t.ret, s)
    return False


def unify(t1, t2, s):
    t1 = apply_subst(t1, s)
    t2 = apply_subst(t2, s)
    if t1 == t2:
        return s
    if isinstance(t1, TVar):
        if occurs(t1, t2, s):
            raise ValueError("Infinite type")
        return {**s, t1: t2}
    if isinstance(t2, TVar):
        if occurs(t2, t1, s):
            raise ValueError("Infinite type")
        return {**s, t2: t1}
    if isinstance(t1, TList) and isinstance(t2, TList):
        return unify(t1.e, t2.e, s)
    if isinstance(t1, TRef) and isinstance(t2, TRef):
        return unify(t1.e, t2.e, s)
    if isinstance(t1, TArrow) and isinstance(t2, TArrow):
        if len(t1.args) != len(t2.args):
            raise ValueError("Arity mismatch")
        for a1, a2 in zip(t1.args, t2.args):
            s = unify(a1, a2, s)
        return unify(t1.ret, t2.ret, s)
    raise ValueError("Type mismatch")


def free_vars(t):
    if isinstance(t, TVar):
        return {t}
    if isinstance(t, TList):
        return free_vars(t.e)
    if isinstance(t, TRef):
        return free_vars(t.e)
    if isinstance(t, TArrow):
        r = set()
        for a in t.args:
            r |= free_vars(a)
        r |= free_vars(t.ret)
        return r
    return set()


def check_value(t):
    if not isinstance(t, tuple) or not t:
        return False
    tag = t[0]
    if tag in ("int", "bool", "str", "unit", "var", "fn"):
        return True
    if tag == "nil":
        return True
    if tag == "cons":
        return len(t) == 3 and check_value(t[1]) and check_value(t[2])
    return False


def instantiate_scheme(scheme, s):
    new_s = {}
    for v in scheme.tvs:
        if v not in s:
            new_s[v] = fresh()
    return apply_subst(scheme.t, new_s), {**s, **new_s}


def generalize(t, env, s):
    env_fv = set()
    for t2 in env.values():
        if isinstance(t2, TScheme):
            env_fv |= free_vars(apply_subst(t2.t, s)) - t2.tvs
        else:
            env_fv |= free_vars(apply_subst(t2, s))
    quantified = free_vars(t) - env_fv
    return TScheme(quantified, t)


def infer(term, env, s):
    if not isinstance(term, tuple) or not term:
        raise ValueError("Malformed")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed tag")

    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool):
            raise ValueError("Malformed int")
        return TInt(), s

    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Malformed bool")
        return TBool(), s

    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Malformed str")
        return TString(), s

    elif tag == "unit":
        if len(term) != 1:
            raise ValueError("Malformed unit")
        return TUnit(), s

    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed var")
        name = term[1]
        if name not in env:
            raise ValueError("Unbound")
        val = env[name]
        if isinstance(val, TScheme):
            t, s = instantiate_scheme(val, s)
            return t, s
        return apply_subst(val, s), s

    elif tag == "fn":
        if len(term) != 3 or not isinstance(term[1], tuple) or not term[1]:
            raise ValueError("Malformed fn")
        params, body = term[1], term[2]
        if not all(isinstance(p, str) and p for p in params):
            raise ValueError("Malformed fn params")
        if len(params) != len(set(params)):
            raise ValueError("Malformed fn params")
        new_env = {**env}
        ptypes = []
        for p in params:
            new_env[p] = fresh()
            ptypes.append(new_env[p])
        ret, s = infer(body, new_env, s)
        return TArrow(tuple(ptypes), ret), s

    elif tag == "call":
        if len(term) != 3 or not isinstance(term[2], tuple) or not term[2]:
            raise ValueError("Malformed call")
        f, args = term[1], term[2]
        ft, s = infer(f, env, s)
        arg_types = [fresh() for _ in args]
        ret_type = fresh()
        s = unify(ft, TArrow(tuple(arg_types), ret_type), s)
        for i, a in enumerate(args):
            at, s = infer(a, env, s)
            s = unify(at, arg_types[i], s)
        return apply_subst(ret_type, s), s

    elif tag == "let":
        if len(term) != 4 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed let")
        name, e1, e2 = term[1], term[2], term[3]
        t1, s = infer(e1, env, s)
        t1 = apply_subst(t1, s)
        if check_value(e1):
            t1 = generalize(t1, env, s)
        new_env = {**env, name: t1}
        return infer(e2, new_env, s)

    elif tag == "letrec":
        if len(term) != 4 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed letrec")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(e1, tuple) or not e1 or e1[0] != "fn":
            raise ValueError("letrec requires fn")
        ntype = fresh()
        t1, s = infer(e1, {**env, name: ntype}, s)
        t1 = apply_subst(t1, s)
        if not isinstance(t1, TArrow):
            raise ValueError("letrec body must be function")
        s = unify(ntype, t1, s)
        ntype = apply_subst(ntype, s)
        ntype = generalize(ntype, env, s)
        new_env = {**env, name: ntype}
        return infer(e2, new_env, s)

    elif tag == "nil":
        if len(term) != 1:
            raise ValueError("Malformed nil")
        return TList(fresh()), s

    elif tag == "cons":
        if len(term) != 3:
            raise ValueError("Malformed cons")
        h, t = term[1], term[2]
        ht, s = infer(h, env, s)
        tt, s = infer(t, env, s)
        lt = TList(ht)
        s = unify(tt, lt, s)
        return apply_subst(lt, s), s

    elif tag == "match":
        if len(term) != 6:
            raise ValueError("Malformed match")
        s_term, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if (not isinstance(hn, str) or not hn or
                not isinstance(tn, str) or not tn):
            raise ValueError("Malformed match names")
        if hn == tn:
            raise ValueError("Match names must differ")
        st, s = infer(s_term, env, s)
        elem = fresh()
        s = unify(st, TList(elem), s)
        st = apply_subst(st, s)
        if not isinstance(st, TList):
            raise ValueError("Match requires List")
        elem = st.e
        ty1, s = infer(e_nil, env, s)
        new_env = {**env, hn: elem, tn: st}
        ty2, s = infer(e_cons, new_env, s)
        s = unify(ty1, ty2, s)
        return apply_subst(ty1, s), s

    elif tag == "ref":
        if len(term) != 2:
            raise ValueError("Malformed ref")
        et, s = infer(term[1], env, s)
        return TRef(et), s

    elif tag == "get":
        if len(term) != 2:
            raise ValueError("Malformed get")
        rt, s = infer(term[1], env, s)
        elem = fresh()
        s = unify(rt, TRef(elem), s)
        rt = apply_subst(rt, s)
        if not isinstance(rt, TRef):
            raise ValueError("Get requires Ref")
        return rt.e, s

    elif tag == "set":
        if len(term) != 3:
            raise ValueError("Malformed set")
        r, e = term[1], term[2]
        rt, s = infer(r, env, s)
        elem = fresh()
        s = unify(rt, TRef(elem), s)
        rt = apply_subst(rt, s)
        if not isinstance(rt, TRef):
            raise ValueError("Set requires Ref")
        et, s = infer(e, env, s)
        s = unify(et, rt.e, s)
        return TUnit(), s

    else:
        raise ValueError("Unknown tag")


def print_type(t):
    vars_list = []

    def collect(typ):
        if isinstance(typ, TVar):
            if typ not in vars_list:
                vars_list.append(typ)
        elif isinstance(typ, TList):
            collect(typ.e)
        elif isinstance(typ, TRef):
            collect(typ.e)
        elif isinstance(typ, TArrow):
            for a in typ.args:
                collect(a)
            collect(typ.ret)

    collect(t)
    vm = {v: "t{}".format(i + 1) for i, v in enumerate(vars_list)}

    def fmt(typ):
        if isinstance(typ, TVar):
            return vm[typ]
        if isinstance(typ, TInt):
            return "Int"
        if isinstance(typ, TBool):
            return "Bool"
        if isinstance(typ, TString):
            return "Str"
        if isinstance(typ, TUnit):
            return "Unit"
        if isinstance(typ, TList):
            return "List<{}>".format(fmt(typ.e))
        if isinstance(typ, TRef):
            return "Ref<{}>".format(fmt(typ.e))
        if isinstance(typ, TArrow):
            ret_s = fmt(typ.ret)
            if len(typ.args) == 1:
                p = fmt(typ.args[0])
                if isinstance(typ.args[0], TArrow):
                    return "({}) -> {}".format(p, ret_s)
                return "{} -> {}".format(p, ret_s)
            args_s = ", ".join(fmt(a) for a in typ.args)
            return "({}) -> {}".format(args_s, ret_s)
        return str(typ)

    return fmt(t)


def weak_infer(term):
    global _fresh
    _fresh = 0
    a = fresh()
    env = {
        "plus": TArrow((TInt(), TInt()), TInt()),
        "eq": TScheme({a}, TArrow((a, a), TBool())),
        "size": TArrow((TString(),), TInt()),
    }
    try:
        res, s = infer(term, env, {})
        res = apply_subst(res, s)
        return print_type(res)
    except ValueError:
        raise

