        if len(term) != 4:
            raise ValueError("Bad if")
        c, t, e = term[1], term[2], term[3]
        c_type = infer(c, env, env_fv, counter, subst)
        unify(c_type, Type('Bool'), subst)
        t_type = infer(t, env, env_fv, counter, subst)
        e_type = infer(e, env, env_fv, counter, subst)
        unify(t_type, e_type, subst)
        return t_type

    elif tag == "let":
        if len(term) != 4:
            raise ValueError("Bad let")
        x, e1, e2 = term[1], term[2], term[3]
        if not isinstance(x, str) or not x:
            raise ValueError("Bad let name")
        e1_type = infer(e1, env, env_fv, counter, subst)
        t1 = apply_subst(e1_type, subst)
        generic = free_vars(t1) - env_fv
        env = {**env, x: (t1, generic)}
        # env_fv unchanged: generic variables are not free
        return infer(e2, env, env_fv, counter, subst)

    elif tag == "letrec":
        if len(term) != 3:
            raise ValueError("Bad letrec")
        group, body = term[1], term[2]
        if not isinstance(group, tuple) or len(group) == 0:
            raise ValueError("Bad letrec group")
        names = []
        exprs = []
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2:
                raise ValueError("Bad letrec item")
            n, e = item
            if not isinstance(n, str) or not n:
                raise ValueError("Bad letrec name")
            if n in names:
                raise ValueError("Duplicate letrec name")
            names.append(n)
            exprs.append(e)

        # Save outer free variables
        outer_fv = set(env_fv)
        # Add monomorphic recursive names
        rec_env = {**env}
        rec_env_fv = set(env_fv)
        for n in names:
            v = fresh_var(counter)
            rec_env[n] = (v, set())
            rec_env_fv.add(v.args[0])

        inferred = []
        for e in exprs:
            inferred.append(infer(e, rec_env, rec_env_fv, counter, subst))

        # Generalize each name for the body
        body_env = {**env}
        body_env_fv = set(env_fv)  # outer fv, not including rec names
        for n, t in zip(names, inferred):
            t_subst = apply_subst(t, subst)
            generic = free_vars(t_subst) - outer_fv
            body_env[n] = (t_subst, generic)
