        if len(term) != 3:
            raise ValueError("Bad app")
        f, a = term[1], term[2]
        f_type = infer(f, env, subst, counter)
        a_type = infer(a, env, subst, counter)
        res_type = fresh_var(counter)
        unify(f_type, Type('Arrow', a_type, res_type), subst)
        return apply_subst(res_type, subst)

    # if
    if tag == "if":
        if len(term) != 4:
            raise ValueError("Bad if")
        c, t, e = term[1], term[2], term[3]
        c_type = infer(c, env, subst, counter)
        unify(c_type, Type('Bool'), subst)
        t_type = infer(t, env, subst, counter)
        e_type = infer(e, env, subst, counter)
        unify(t_type, e_type, subst)
        return apply_subst(t_type, subst)

    # let
    if tag == "let":
        if len(term) != 4:
            raise ValueError("Bad let")
        x, e1, e2 = term[1], term[2], term[3]
        if not isinstance(x, str) or not x:
            raise ValueError("Bad let name")
        e1_type = infer(e1, env, subst, counter)
        scheme = generalize(e1_type, env, subst, counter)
        env_x = dict(env)
        env_x[x] = scheme
        return infer(e2, env_x, subst, counter)

    # letrec
    if tag == "letrec":
        if len(term) != 3:
            raise ValueError("Bad letrec")
        group, body = term[1], term[2]
        if not isinstance(group, tuple) or len(group) == 0:
            raise ValueError("Bad letrec group")

        names = []
        exprs = []
        seen = set()
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2:
                raise ValueError("Bad letrec item")
            n, e = item
            if not isinstance(n, str) or not n:
                raise ValueError("Bad letrec name")
            if n in seen:
                raise ValueError("Duplicate letrec name")
            seen.add(n)
            names.append(n)
            exprs.append(e)

        rec_env = dict(env)
        for n in names:
            rec_env[n] = fresh_var(counter)

        inferred = []
        for e in exprs:
            inferred.append(infer(e, rec_env, subst, counter))

        outer_free = free_env_vars(env, subst)
        schemes = []
        for t in inferred:
            t = apply_subst(t, subst)
            quant = free_vars(t) - outer_free
            schemes.append(TypeScheme(t, quant))

        body_env = dict(env)
        for n, s in zip(names, schemes):
            body_env[n] = s
        return infer(body, body_env, subst, counter)

    # tuple
    if tag == "tuple":
        n = len(term) - 1
        if n == 1:
            raise ValueError("Tuple n=1 not allowed")
        types = []
        for i in range(1, len(term)):
            types.append(infer(term[i], env, subst, counter))
        return Type('Tuple', *types)

    # projection
    if tag == "proj":
        if len(term) != 4:
            raise ValueError("Bad proj")
        i, n, e = term[1], term[2], term[3]
        if not isinstance(i, int) or isinstance(i, bool):
            raise ValueError("Bad proj i")
        if not isinstance(n, int) or isinstance(n, bool):
            raise ValueError("Bad proj n")
        if n < 2:
            raise ValueError("proj n < 2")
        if i < 0 or i >= n:
            raise ValueError("proj i out of bounds")

        e_type = infer(e, env, subst, counter)
        e_type = apply_subst(e_type, subst)
        if e_type.tag != 'Tuple' or len(e_type.args) != n:
            raise ValueError("proj type mismatch")
        return e_type.args[i]

    raise ValueError(f"Unknown tag: {tag}")


def output_name(index):
    res = []
    index += 1
    while index > 0:
        index, rem = divmod(index - 1, 26)
        res.append(chr(ord('a') + rem))
    return ''.join(reversed(res))


def rename_vars(t, mapping, counter):
    if t.tag == 'Var':
        name = t.args[0]
        if name not in mapping:
            mapping[name] = output_name(counter[0])
            counter[0] += 1
        return Type('Var', mapping[name])
    return Type(t.tag, *(rename_vars(a, mapping, counter) for a in t.args))


def format_type(t):
    if t.tag == 'Int':
        return 'Int'
    if t.tag == 'Bool':
        return 'Bool'
    if t.tag == 'Var':
        return t.args[0]
    if t.tag == 'Arrow':
        return f"(-> {format_type(t.args[0])} {format_type(t.args[1])})"
    if t.tag == 'List':
        return f"(List {format_type(t.args[0])})"
    if t.tag == 'Tuple':
        if len(t.args) == 0:
            return "(Tuple)"
        return f"(Tuple {' '.join(format_type(a) for a in t.args)})"
    raise ValueError(f"Unknown type tag: {t.tag}")


def group_type(term):
    # Initial environment
    q = [0]

    def qvar():
        name = f"q{q[0]}"
        q[0] += 1
        return Type('Var', name)

    qa = qvar()
    qb = qvar()
    qc = qvar()
    qd = qvar()
    qe = qvar()
    qf = qvar()

    init_env = {
        "add": Type('Arrow', Type('Int'), Type('Arrow', Type('Int'), Type('Int'))),
        "eq": TypeScheme(Type('Arrow', qa, Type('Arrow', qa, Type('Bool'))), {qa.args[0]}),
        "nil": TypeScheme(Type('List', qb), {qb.args[0]}),
        "cons": TypeScheme(
            Type('Arrow', qc, Type('Arrow', Type('List', qc), Type('List', qc))),
            {qc.args[0]}
        ),
        "head": TypeScheme(Type('Arrow', Type('List', qd), qd), {qd.args[0]}),
        "tail": TypeScheme(
            Type('Arrow', Type('List', qe), Type('List', qe)),
            {qe.args[0]}
        ),
        "isnil": TypeScheme(Type('Arrow', Type('List', qf), Type('Bool')), {qf.args[0]}),
    }

    subst = {}
    counter = [0]
    result = infer(term, init_env, subst, counter)
    result = apply_subst(result, subst)

    mapping = {}
    rename_counter = [0]
    result = rename_vars(result, mapping, rename_counter)
    return format_type(result)

