class Type:
    __slots__ = ("tag", "args")

    def __init__(self, tag, *args):
        self.tag = tag
        self.args = args

    def __eq__(self, other):
        return (
            isinstance(other, Type)
            and self.tag == other.tag
            and self.args == other.args
        )

    def __hash__(self):
        return hash((self.tag, self.args))


class TypeScheme:
    __slots__ = ("ty", "quant")

    def __init__(self, ty, quant):
        self.ty = ty
        self.quant = quant


def fresh_var(counter):
    name = f"u{counter[0]}"
    counter[0] += 1
    return Type("Var", name)


def free_vars(t):
    if t.tag == "Var":
        return {t.args[0]}
    res = set()
    for a in t.args:
        res |= free_vars(a)
    return res


def apply_subst(t, subst):
    if t.tag == "Var":
        name = t.args[0]
        if name in subst:
            return apply_subst(subst[name], subst)
        return t
    return Type(t.tag, *(apply_subst(a, subst) for a in t.args))


def replace_var(t, name, new_var):
    if t.tag == "Var":
        return new_var if t.args[0] == name else t
    return Type(t.tag, *(replace_var(a, name, new_var) for a in t.args))


def occurs_in(name, t):
    if t.tag == "Var":
        return t.args[0] == name
    return any(occurs_in(name, a) for a in t.args)


def unify(t1, t2, subst):
    t1 = apply_subst(t1, subst)
    t2 = apply_subst(t2, subst)

    if t1 == t2:
        return

    if t1.tag == "Var":
        if occurs_in(t1.args[0], t2):
            raise ValueError("Infinite type")
        subst[t1.args[0]] = t2
    elif t2.tag == "Var":
        if occurs_in(t2.args[0], t1):
            raise ValueError("Infinite type")
        subst[t2.args[0]] = t1
    elif t1.tag == "Arrow" and t2.tag == "Arrow":
        unify(t1.args[0], t2.args[0], subst)
        unify(t1.args[1], t2.args[1], subst)
    elif t1.tag == "List" and t2.tag == "List":
        unify(t1.args[0], t2.args[0], subst)
    elif t1.tag == "Tuple" and t2.tag == "Tuple":
        if len(t1.args) != len(t2.args):
            raise ValueError("Tuple size mismatch")
        for a1, a2 in zip(t1.args, t2.args):
            unify(a1, a2, subst)
    else:
        raise ValueError("Type mismatch")


def free_env_vars(env, subst):
    res = set()
    for entry in env.values():
        if isinstance(entry, TypeScheme):
            t = apply_subst(entry.ty, subst)
            res |= free_vars(t) - entry.quant
        else:
            res |= free_vars(apply_subst(entry, subst))
    return res


def instantiate(entry, subst, counter):
    if isinstance(entry, TypeScheme):
        t = entry.ty
        for q in entry.quant:
            t = replace_var(t, q, fresh_var(counter))
        return apply_subst(t, subst)
    else:
        return apply_subst(entry, subst)


def generalize(t, env, subst, counter):
    t = apply_subst(t, subst)
    quant = free_vars(t) - free_env_vars(env, subst)
    return TypeScheme(t, quant)


def infer(term, env, subst, counter):
    # Integer literal
    if isinstance(term, int) and not isinstance(term, bool):
        return Type("Int")

    # Booleans
    if term is True or term is False:
        return Type("Bool")

    # Variable
    if isinstance(term, str):
        if not term:
            raise ValueError("Empty variable name")
        if term in env:
            return instantiate(env[term], subst, counter)
        raise ValueError(f"Unbound variable: {term}")

    # Malformed non-tuple
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")

    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Bad tag")

    # lambda
    if tag == "lam":
        if len(term) != 3:
            raise ValueError("Bad lam")
        x, body = term[1], term[2]
        if not isinstance(x, str) or not x:
            raise ValueError("Bad param name")
        x_type = fresh_var(counter)
        env_x = dict(env)
        env_x[x] = x_type
        body_type = infer(body, env_x, subst, counter)
        return Type("Arrow", x_type, body_type)

    # application
    if tag == "app":
        if len(term) != 3:
            raise ValueError("Bad app")
        f, a = term[1], term[2]
        f_type = infer(f, env, subst, counter)
        a_type = infer(a, env, subst, counter)
        res_type = fresh_var(counter)
        unify(f_type, Type("Arrow", a_type, res_type), subst)
        return apply_subst(res_type, subst)

    # if
    if tag == "if":
        if len(term) != 4:
            raise ValueError("Bad if")
        c, t, e = term[1], term[2], term[3]
        c_type = infer(c, env, subst, counter)
        unify(c_type, Type("Bool"), subst)
        t_type = infer(t, env, subst, counter)
        e_type = infer(e, env, subst, counter)
        unify(t_type, e_type, subst)
        return apply_subst(t_type, subst)

    # let
    if tag == "let":
        if len(term) != 4:
            raise ValueError("Bad let")
        x, e1, e2 = term[1], term[2], term[3]
        if not isinstance(x, str) or not x:
            raise ValueError("Bad let name")
        e1_type = infer(e1, env, subst, counter)
        scheme = generalize(e1_type, env, subst, counter)
        env_x = dict(env)
        env_x[x] = scheme
        return infer(e2, env_x, subst, counter)

    # letrec
    if tag == "letrec":
        if len(term) != 3:
            raise ValueError("Bad letrec")
        group, body = term[1], term[2]
        if not isinstance(group, tuple) or len(group) == 0:
            raise ValueError("Bad letrec group")

        names = []
        exprs = []
        seen = set()
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2:
                raise ValueError("Bad letrec item")
            n, e = item
            if not isinstance(n, str) or not n:
                raise ValueError("Bad letrec name")
            if n in seen:
                raise ValueError("Duplicate letrec name")
            seen.add(n)
            names.append(n)
            exprs.append(e)

        rec_env = dict(env)
        for n in names:
            rec_env[n] = fresh_var(counter)

        inferred = []
        for e in exprs:
            inferred.append(infer(e, rec_env, subst, counter))

        outer_free = free_env_vars(env, subst)
        schemes = []
        for t in inferred:
            t = apply_subst(t, subst)
            quant = free_vars(t) - outer_free
            schemes.append(TypeScheme(t, quant))

        body_env = dict(env)
        for n, s in zip(names, schemes):
            body_env[n] = s
        return infer(body, body_env, subst, counter)

    # tuple
    if tag == "tuple":
        n = len(term) - 1
        if n == 1:
            raise ValueError("Tuple n=1 not allowed")
        types = []
        for i in range(1, len(term)):
            types.append(infer(term[i], env, subst, counter))
        return Type("Tuple", *types)

    # projection
    if tag == "proj":
        if len(term) != 4:
            raise ValueError("Bad proj")
        i, n, e = term[1], term[2], term[3]
        if not isinstance(i, int) or isinstance(i, bool):
            raise ValueError("Bad proj i")
        if not isinstance(n, int) or isinstance(n, bool):
            raise ValueError("Bad proj n")
        if n < 2:
            raise ValueError("proj n < 2")
        if i < 0 or i >= n:
            raise ValueError("proj i out of bounds")

        e_type = infer(e, env, subst, counter)
        comp_types = [fresh_var(counter) for _ in range(n)]
        unify(e_type, Type("Tuple", *comp_types), subst)
        return apply_subst(comp_types[i], subst)

    raise ValueError(f"Unknown tag: {tag}")


