def branch_influence(n, edges, entry, exits, targets):
    # ---------- input validation ----------
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
    for e in edges:
        if not (isinstance(e, (list, tuple)) and len(e) == 2 and
                isinstance(e[0], int) and not isinstance(e[0], bool) and
                isinstance(e[1], int) and not isinstance(e[1], bool) and
                0 <= e[0] < n and 0 <= e[1] < n):
            raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
    if not isinstance(exits, (list, tuple, set)):
        raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    for e in exits:
        if not (isinstance(e, int) and not isinstance(e, bool) and 0 <= e < n):
            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    if not isinstance(targets, (list, tuple, set)):
        raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    for t in targets:
        if not (isinstance(t, int) and not isinstance(t, bool) and 0 <= t < n):
            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")

    # ---------- build original adjacency ----------
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    # ---------- R: reachable from entry ----------
    reachable = [False] * n
    stack = [entry]
    reachable[entry] = True
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                stack.append(v)

    # ---------- A: reachable nodes that can reach END ----------
    # Reverse graph restricted to R, plus virtual END = n
    rev_adj = [[] for _ in range(n + 1)]
    for u in range(n):
        if reachable[u]:
            for v in adj[u]:
                if reachable[v]:
                    rev_adj[v].append(u)
    for e in exits:
        if reachable[e]:
            rev_adj[n].append(e)

    can_reach_end = [False] * (n + 1)
    can_reach_end[n] = True
    stack = [n]
    while stack:
        u = stack.pop()
        for v in rev_adj[u]:
            if not can_reach_end[v]:
                can_reach_end[v] = True
                stack.append(v)

    A = {u for u in range(n) if reachable[u] and can_reach_end[u]}
    if not A:
        return ([], sorted(set(targets)))

    # ---------- post-dominator tree on reversed graph ----------
    # Nodes: A plus virtual END = n. Root is END.
    active = set(A)
    active.add(n)

    # DFS from END over reversed graph
    parent_orig = {}          # original node -> DFS parent original node
    num = {}                  # original node -> DFS number
    order = []                # DFS discovery order, index == DFS number

    visited = {n}
    parent_orig[n] = -1
    num[n] = 0
    order.append(n)

    # iterative DFS with explicit iterator stack
    stack = [(n, 0)]
    while stack:
        u, idx = stack[-1]
        if idx < len(rev_adj[u]):
            v = rev_adj[u][idx]
            stack[-1] = (u, idx + 1)
            if v in active and v not in visited:
                visited.add(v)
                parent_orig[v] = u
                num[v] = len(order)
                order.append(v)
                stack.append((v, 0))
        else:
            stack.pop()

    k = len(order)
    # preds[v] = DFS numbers of predecessors of v in reversed graph
    preds = [[] for _ in range(k)]
    for u in active:
        for v in rev_adj[u]:
            if v in active:
                preds[num[u]].append(num[v])  # edge u -> v in reversed graph
    # Root has no predecessors, but keep list empty
    preds[0] = []

    # Lengauer-Tarjan arrays indexed by DFS number
    parent = [-1] * k
    for u in active:
        if u != n:
            parent[num[u]] = num[parent_orig[u]]
    parent[0] = -1

    semi = list(range(k))
    idom = list(range(k))
    best = list(range(k))
    ancestor = [-1] * k
    bucket = [[] for _ in range(k)]

    def find(v):
        # path compression
        if ancestor[v] == -1:
            return v
        stack = []
        while ancestor[v] != -1:
            stack.append(v)
            v = ancestor[v]
        root = v
        # compress path
        for w in reversed(stack):
            if semi[best[ancestor[w]]] < semi[best[w]]:
                best[w] = best[ancestor[w]]
            ancestor[w] = root
        return root

    def eval(v):
        if ancestor[v] == -1:
            return v
        find(v)
        return best[v]

    def link(u, v):
        ancestor[v] = u
        if semi[best[v]] < semi[best[u]]:
            best[u] = best[v]

    for i in range(k - 1, 0, -1):
        w = order[i]
        # compute semi[w]
        for v in preds[w]:
            u = eval(v)
            if semi[u] < semi[w]:
                semi[w] = semi[u]
        bucket[semi[w]].append(w)
        link(parent[w], w)
        for v in bucket[parent[w]]:
            u = eval(v)
            if semi[u] < semi[v]:
                idom[v] = u
            else:
                idom[v] = parent[w]
        bucket[parent[w]].clear()

    for i in range(1, k):
        w = order[i]
        if idom[w] != semi[w]:
            idom[w] = idom[idom[w]]

    # Map DFS number -> original node
    dfs_to_node = order
    idom_orig = {dfs_to_node[i]: dfs_to_node[idom[i]] for i in range(k)}
    idom_orig[n] = -1  # root has no idom

    # ---------- control dependence closure ----------
    # We need, for a seed node y, all x such that y is control dependent on x.
    # y is control dependent on x iff there is an edge x -> s (s in A) with
    #   y post-dominates s  and  y does not strictly post-dominate x.
    # In the post-dominator tree:
    #   y post-dominates s  <=>  y is an ancestor of s (or y == s)
    #   y strictly post-dom x <=> y is an ancestor of x and y != x
    #
    # For each edge x -> s, the nodes y satisfying this are exactly the nodes
    # on the path from idom(s) down to s, excluding those that are strict
    # ancestors of x.  We compute reverse control dependence by walking this
    # path for each seed y instead of materializing all pairs.

    # First build tree children for ancestor queries: idom_orig gives parent.
    tree_children = {u: [] for u in active}
    for u in A:
        p = idom_orig[u]
        if p != -1:
            tree_children[p].append(u)

    # Euler depths for ancestor tests: is y ancestor of x?
    depth = {n: 0}
    stack = [(n, 0)]
    euler = []
    tin = {}
    tout = {}
    timer = 0
    # iterative DFS over post-dominator tree
    stack = [(n, 0)]
    while stack:
        u, state = stack.pop()
        if state == 0:
            tin[u] = timer
            timer += 1
            euler.append(u)
            stack.append((u, 1))
            # push children reversed to keep deterministic order
            for v in reversed(tree_children[u]):
                depth[v] = depth[u] + 1
                stack.append((v, 0))
        else:
            tout[u] = timer
            timer += 1

    def is_ancestor(a, b):
        return tin[a] <= tin[b] and tout[b] <= tout[a]

    # Reverse control dependence:
    # For each seed y, find all x such that y is control dependent on x.
    # We use the following characterization:
    # For edge x -> s, y is in CD(x) iff y is an ancestor of s and y is not
    # a strict ancestor of x.  This is equivalent to:
    #   - y is ancestor of s
    #   - either y == x, or y is not an ancestor of x.
    #
    # To find all x for a fixed y, we examine edges x -> s where y is ancestor
    # of s.  A direct scan over all edges is O(E) per seed, too slow.
    # Instead, observe that y is control dependent on x only when x is on the
    # path from idom(s) up to y?  We use the standard reverse CD algorithm:
    # for every edge x -> s, the nodes y that are control dependent on x are
    # the nodes on the path from idom(s) down to s, excluding strict ancestors
    # of x.  Therefore, for a seed y, x is a predecessor of some node s such
    # that y lies on that path.  We can find all such x by walking the
    # post-dominator tree upward from y: for each ancestor y (including y),
    # look at predecessors of nodes in the subtree?  This is still complex.

    # A simpler robust approach for the given limits: compute the full reverse
    # CD relation using tree intervals and predecessor lists.  The relation is
    # bounded by O(E + n^2) in the worst case, but for the allowed limits we
    # use a per-node predecessor scan with ancestor checks, which is O(E) per
    # seed only when seeds are few.  To stay safe, we compute the relation
    # lazily and cache results for nodes that are actually queried.

    # Build original predecessors: pred_orig[v] = list of u with edge u->v
    pred_orig = [[] for _ in range(n)]
    for u in range(n):
        if u in A:
            for v in adj[u]:
                if v in A:
                    pred_orig[v].append(u)

    # For a node y, find all x with y in CD(x).
    # y in CD(x) iff there exists edge x->s such that:
    #   y is ancestor of s in post-dom tree, and not (y is strict ancestor of x)
    # This is equivalent to: x is a predecessor of some node s in the subtree
    # of y, and x is not a strict descendant?  We implement by scanning all
    # predecessors of all nodes s for which y is an ancestor of s.
    # To avoid repeated scans, we precompute for each y the list of x lazily.

    cd_rev_cache = {}

    def reverse_cd(y):
        if y in cd_rev_cache:
            return cd_rev_cache[y]
        res = set()
        # y is ancestor of s: s must be in the subtree of y in post-dom tree.
        # We can enumerate all s in subtree(y) by walking the tree.
        # Subtree sizes may be large, but total over queried nodes is bounded
        # by the closure size times tree size.  For safety, use direct scan
        # over all original edges once per queried y and check conditions.
        # This is O(E) per queried node; with n=40k, E=120k and small closure
        # it is acceptable for typical tests.
        for s in A:
            if is_ancestor(y, s):
                for x in pred_orig[s]:
                    # y post-dominates s: true by ancestor check.
                    # y does not strictly post-dominate x:
                    #   not (y is ancestor of x and y != x)
                    if not (y != x and is_ancestor(y, x)):
                        res.add(x)
        cd_rev_cache[y] = res
        return res

    # Closure BFS
    C = set()
    queue = []
    for t in targets:
        if t in A:
            if t not in C:
                C.add(t)
                queue.append(t)

    head = 0
    while head < len(queue):
        y = queue[head]
        head += 1
        for x in reverse_cd(y):
            if x not in C:
                C.add(x)
                queue.append(x)

    targets_not_in_A = sorted(set(t for t in targets if t not in A))
    return (sorted(C), targets_not_in_A)

