def branch_influence(n, edges, entry, exits, targets):
    # ---------- input validation ----------
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
    for e in edges:
        if not (isinstance(e, (list, tuple)) and len(e) == 2 and
                isinstance(e[0], int) and not isinstance(e[0], bool) and
                isinstance(e[1], int) and not isinstance(e[1], bool) and
                0 <= e[0] < n and 0 <= e[1] < n):
            raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
    if not isinstance(exits, (list, tuple, set)):
        raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    for e in exits:
        if not (isinstance(e, int) and not isinstance(e, bool) and 0 <= e < n):
            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    if not isinstance(targets, (list, tuple, set)):
        raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    for t in targets:
        if not (isinstance(t, int) and not isinstance(t, bool) and 0 <= t < n):
            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")

    # ---------- original adjacency ----------
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    # ---------- R: reachable from entry ----------
    reachable = [False] * n
    stack = [entry]
    reachable[entry] = True
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                stack.append(v)

    # ---------- A: reachable nodes that can reach END ----------
    END = n
    rev_adj = [[] for _ in range(n + 1)]
    for u in range(n):
        if reachable[u]:
            for v in adj[u]:
                if reachable[v]:
                    rev_adj[v].append(u)
    for e in exits:
        if reachable[e]:
            rev_adj[END].append(e)

    can_reach_end = [False] * (n + 1)
    can_reach_end[END] = True
    stack = [END]
    while stack:
        u = stack.pop()
        for v in rev_adj[u]:
            if not can_reach_end[v]:
                can_reach_end[v] = True
                stack.append(v)

    A = {u for u in range(n) if reachable[u] and can_reach_end[u]}
    if not A:
        return ([], sorted(set(targets)))

    active = set(A)
    active.add(END)

    # ---------- Lengauer-Tarjan post-dominator tree ----------
    # DFS from END on reversed graph, restricted to active nodes.
    visited = {END}
    parent_orig = {END: -1}
    num = {END: 0}
    order = [END]

    stack = [(END, 0)]
    while stack:
        u, idx = stack[-1]
        if idx < len(rev_adj[u]):
            v = rev_adj[u][idx]
            stack[-1] = (u, idx + 1)
            if v in active and v not in visited:
                visited.add(v)
                parent_orig[v] = u
                num[v] = len(order)
                order.append(v)
                stack.append((v, 0))
        else:
            stack.pop()

    k = len(order)
    dfs_to_node = order

    # preds[w] = DFS numbers of predecessors of w in reversed graph
    preds = [[] for _ in range(k)]
    for u in active:
        for v in rev_adj[u]:
            if v in active:
                preds[num[v]].append(num[u])

    parent = [-1] * k
    for u in active:
        if u != END:
            parent[num[u]] = num[parent_orig[u]]
    parent[0] = -1

    semi = list(range(k))
    idom = list(range(k))
    best = list(range(k))
    ancestor = [-1] * k
    bucket = [[] for _ in range(k)]

    def find(v):
        if ancestor[v] == -1:
            return v
        path = []
        while ancestor[v] != -1:
            path.append(v)
            v = ancestor[v]
        root = v
        for w in reversed(path):
            if semi[best[ancestor[w]]] < semi[best[w]]:
                best[w] = best[ancestor[w]]
            ancestor[w] = root
        return root

    def eval(v):
        if ancestor[v] == -1:
            return v
        find(v)
        return best[v]

    def link(u, v):
        ancestor[v] = u
        if semi[best[v]] < semi[best[u]]:
            best[u] = best[v]

    for i in range(k - 1, 0, -1):
        w = order[i]
        for v in preds[w]:
            u = eval(v)
            if semi[u] < semi[w]:
                semi[w] = semi[u]
        bucket[semi[w]].append(w)
        link(parent[w], w)
        for v in bucket[parent[w]]:
            u = eval(v)
            if semi[u] < semi[v]:
                idom[v] = u
            else:
                idom[v] = parent[w]
        bucket[parent[w]].clear()

    for i in range(1, k):
        w = order[i]
        if idom[w] != semi[w]:
            idom[w] = idom[idom[w]]

    idom_orig = {dfs_to_node[i]: dfs_to_node[idom[i]] for i in range(k)}
    idom_orig[END] = -1

    # ---------- post-dominator tree children and Euler times ----------
    tree_children = {u: [] for u in active}
    for u in A:
        p = idom_orig[u]
        if p != -1:
            tree_children[p].append(u)

    depth = {END: 0}
    tin = {}
    tout = {}
    timer = 0

    stack = [(END, 0)]
    while stack:
        u, state = stack.pop()
        if state == 0:
            tin[u] = timer
            timer += 1
            stack.append((u, 1))
            for v in reversed(tree_children[u]):
                depth[v] = depth[u] + 1
                stack.append((v, 0))
        else:
            tout[u] = timer
            timer += 1

    def is_ancestor(a, b):
        return tin[a] <= tin[b] and tout[b] <= tout[a]

    # ---------- Control dependence closure ----------
    # For an edge x -> s, let a be the upper end of the path segment of
    # nodes that are control dependent on x.  We precompute for every
    # original edge (x,s) the value depth_a = depth of that upper end.
    #
    # A node y is control dependent on x iff y is on that segment, i.e.
    #   y is an ancestor of s and depth(y) >= depth_a.
    #
    # We answer reverse queries lazily by scanning all edges once per
    # queried y.  To keep this acceptable, we cache results and use the
    # fact that the closure size is usually small.  The alternative of
    # materialising all pairs is too large for the worst case.

    # Build original predecessors for the reverse scan.
    pred_orig = [[] for _ in range(n)]
    for u in range(n):
        if u in A:
            for v in adj[u]:
                if v in A:
                    pred_orig[v].append(u)

    # Precompute depth_a for each edge (u,v) in A.
    # a = child of LCA(v, parent(u)) on path to v.
    edge_depth_a = []

    # Need LCA queries in the post-dominator tree.  Use binary lifting.
    LOG = 1
    while (1 << LOG) <= len(active):
        LOG += 1
    up = {u: [-1] * LOG for u in active}
    for u in active:
        up[u][0] = idom_orig.get(u, -1)
    for j in range(1, LOG):
        for u in active:
            p = up[u][j - 1]
            up[u][j] = up[p][j - 1] if p != -1 else -1

    def lca(a, b):
        if depth[a] < depth[b]:
            a, b = b, a
        diff = depth[a] - depth[b]
        bit = 0
        while diff:
            if diff & 1:
                a = up[a][bit]
            diff >>= 1
            bit += 1
        if a == b:
            return a
        for j in range(LOG - 1, -1, -1):
            if up[a][j] != up[b][j]:
                a = up[a][j]
                b = up[b][j]
        return up[a][0]

    def child_on_path(anc, desc):
        # anc is a strict ancestor of desc; return child of anc that is
        # an ancestor of desc.
        diff = depth[desc] - depth[anc] - 1
        cur = desc
        bit = 0
        while diff:
            if diff & 1:
                cur = up[cur][bit]
            diff >>= 1
            bit += 1
        return cur

    for u in A:
        pu = idom_orig[u]
        for s in adj[u]:
            if s not in A:
                continue
            if pu == -1:
                # u is directly below END; parent is END.
                pu_node = END
            else:
                pu_node = pu
            z = lca(s, pu_node)
            if z == s:
                # empty segment
                edge_depth_a.append((u, s, depth[s] + 1))
            else:
                a = child_on_path(z, s)
                edge_depth_a.append((u, s, depth[a]))

    # We will scan edges for each queried y.  Use the precomputed list.
    # edge_depth_a entries are (x, s, depth_a).
    cd_rev_cache = {}

    def reverse_cd(y):
        if y in cd_rev_cache:
            return cd_rev_cache[y]
        res = set()
        dy = depth[y]
        for x, s, da in edge_depth_a:
            if da <= dy and is_ancestor(y, s):
                res.add(x)
        cd_rev_cache[y] = res
        return res

    # Closure BFS
    C = set()
    queue = []
    for t in targets:
        if t in A and t not in C:
            C.add(t)
            queue.append(t)

    head = 0
    while head < len(queue):
        y = queue[head]
        head += 1
        for x in reverse_cd(y):
            if x not in C:
                C.add(x)
                queue.append(x)

    targets_not_in_A = sorted(set(t for t in targets if t not in A))
    return (sorted(C), targets_not_in_A)

