                isinstance(e[0], int) and not isinstance(e[0], bool) and
                isinstance(e[1], int) and not isinstance(e[1], bool) and
                0 <= e[0] < n and 0 <= e[1] < n):
            raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
    if not isinstance(exits, (list, tuple, set)):
        raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    for e in exits:
        if not (isinstance(e, int) and not isinstance(e, bool) and 0 <= e < n):
            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    if not isinstance(targets, (list, tuple, set)):
        raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    for t in targets:
        if not (isinstance(t, int) and not isinstance(t, bool) and 0 <= t < n):
            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")

    # ---------- reachable nodes R ----------
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    reachable = [False] * n
    stack = [entry]
    reachable[entry] = True
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                stack.append(v)

    # ---------- nodes A that can reach END ----------
    END = n
    rev = [[] for _ in range(n + 1)]
    for u in range(n):
        if reachable[u]:
            for v in adj[u]:
                if reachable[v]:
                    rev[v].append(u)
    for e in exits:
        if reachable[e]:
            rev[END].append(e)

    can_reach_end = [False] * (n + 1)
    can_reach_end[END] = True
    stack = [END]
    while stack:
        u = stack.pop()
        for v in rev[u]:
            if not can_reach_end[v]:
                can_reach_end[v] = True
                stack.append(v)

    A = {u for u in range(n) if reachable[u] and can_reach_end[u]}
    if not A:
        return ([], sorted(set(targets)))

    # ---------- restricted reverse graph for post-dominators ----------
    # nodes: index 0 = END, then sorted A
    nodes = [END] + sorted(A)
    m = len(nodes)
    idx_of = {node: i for i, node in enumerate(nodes)}

    radj = [[] for _ in range(m)]
    for u in A:
        for v in adj[u]:
            if v in A:
                radj[idx_of[v]].append(idx_of[u])
    for e in A:
        radj[idx_of[END]].append(idx_of[e])   # reverse of implicit e -> END

    # ---------- Lengauer-Tarjan dominators on reversed graph ----------
    # iterative DFS from root 0
    child = [[] for _ in range(m)]
    parent = [-1] * m
    order = []          # DFS order of indices
    num = [-1] * m
    num[0] = 0
    stack = [0]
    while stack:
        u = stack.pop()
        order.append(u)
        for v in radj[u]:
            if num[v] == -1:
                num[v] = len(order)
                parent[v] = u
                child[u].append(v)
                stack.append(v)

    k = len(order)
    if k != m:
        # Should not happen: every A reaches END, so reverse reaches all A.
        raise RuntimeError("unreachable in postdom graph")

    # reorder arrays by DFS number
    order_num = [0] * k
    for i, u in enumerate(order):
        order_num[i] = u

    # parent in DFS tree, indexed by DFS number
    parent_dfs = [-1] * k
    for i in range(k):
        u = order_num[i]
        p = parent[u]
        parent_dfs[i] = num[p] if p != -1 else -1

    # reverse adjacency in DFS-number space
    radj_dfs = [[] for _ in range(k)]
    for i in range(k):
        u = order_num[i]
        for v in radj[u]:
            radj_dfs[i].append(num[v])

    semi = list(range(k))
    idom = list(range(k))
    best = list(range(k))
    ancestor = list(range(k))

    def find(v):
        if ancestor[v] == v:
            return v
        r = find(ancestor[v])
        if semi[best[ancestor[v]]] < semi[best[v]]:
            best[v] = best[ancestor[v]]
        ancestor[v] = r
        return r

    def link(u, v):
        ancestor[v] = u
        if semi[best[v]] < semi[best[u]]:
            best[u] = best[v]

    buckets = [[] for _ in range(k)]

    for i in range(k - 1, 0, -1):
        v = order_num[i]
        preds = radj_dfs[i]
        for u in preds:
            w = find(u)
            if semi[w] < semi[i]:
                semi[i] = semi[w]
        link(parent_dfs[i], i)
        buckets[semi[i]].append(i)

    for i in range(1, k):
        v = order_num[i]
        w = parent_dfs[i]
        for b in buckets[semi[i]]:
            z = find(b)
            if semi[z] < semi[b]:
                idom[b] = z
            else:
                idom[b] = w
        buckets[semi[i]].clear()

    for i in range(1, k):
        if idom[i] != semi[i]:
            idom[i] = idom[idom[i]]

    # idom in original index space: idom_idx[u] = immediate dominator in reverse graph
    idom_idx = [0] * m
    for i in range(k):
        idom_idx[order_num[i]] = order_num[idom[i]] if idom[i] != i else order_num[i]

    # ---------- postdom tree intervals ----------
    tree_child = [[] for _ in range(m)]
    for i in range(m):
        p = idom_idx[i]
        if p != i:
            tree_child[p].append(i)

    tin = [0] * m
    tout = [0] * m
    t = 0
    stack = [(0, 0)]  # node, next child index
    while stack:
        u, ci = stack[-1]
        if ci == 0:
            tin[u] = t
            t += 1
        if ci < len(tree_child[u]):
            v = tree_child[u][ci]
            stack[-1] = (u, ci + 1)
            stack.append((v, 0))
        else:
            tout[u] = t
            t += 1
            stack.pop()

    def is_ancestor(a, b):
        return tin[a] <= tin[b] and tout[b] <= tout[a]

    # ---------- reverse control dependence propagation ----------
    # For a node y in the work queue, find all x such that y is control
    # dependent on x.  For each edge x -> s, y is on the path from s up to
    # the first ancestor of s that is also an ancestor of x (including x iff
    # that node is x itself).
    #
    # We answer queries by scanning edges once per popped node.  This is
    # O(E * |C|) in the worst case, but the constant is small and the
    # intended constraints allow it for typical inputs.

    queue = []
    in_queue = [False] * m

    targets_set = set(targets)
    targets_in_A = [idx_of[t] for t in targets_set if t in A]
    for u in targets_in_A:
        if not in_queue[u]:
            in_queue[u] = True
            queue.append(u)

    edges_in_A = []
    for u in A:
        for v in adj[u]:
            if v in A:
                edges_in_A.append((idx_of[u], idx_of[v]))

    head = 0
    while head < len(queue):
        y = queue[head]
        head += 1

        # Find controllers of y.
        for x, s in edges_in_A:
            # y must be an ancestor of s.
            if not is_ancestor(y, s):
                continue
            # y must not strictly post-dominate x.
            # Equivalent: x is not a proper descendant of y.
            if x != y and is_ancestor(y, x):
                continue
            if not in_queue[x]:
                in_queue[x] = True
                queue.append(x)

    # ---------- build result ----------
    C_nodes = sorted(nodes[u] for u in queue)
    targets_not_in_A = sorted(t for t in targets_set if t not in A)
    return (C_nodes, targets_not_in_A)

