        idom_pd[num_to_pd[i]] = num_to_pd[idom[i]]

    # ---------- postdominator tree and Euler intervals ----------
    tree_child = [[] for _ in range(Npd)]
    for i in range(Npd):
        p = idom_pd[i]
        if p != i:
            tree_child[p].append(i)

    tin = [0] * Npd
    tout = [0] * Npd
    timer = 0
    stack = [(0, 0)]
    while stack:
        u, ci = stack[-1]
        if ci == 0:
            tin[u] = timer
            timer += 1
        if ci < len(tree_child[u]):
            v = tree_child[u][ci]
            stack[-1] = (u, ci + 1)
            stack.append((v, 0))
        else:
            tout[u] = timer
            timer += 1
            stack.pop()

    def is_ancestor(a, b):
        return tin[a] <= tin[b] and tout[b] <= tout[a]

    # ---------- control dependence propagation ----------
    # For each edge x -> s in the restricted graph, y controls x if
    # y postdominates s and y does not strictly postdominate x.
    edges_in_A = []
    for u in A_sorted:
        ui = pd_of[u]
        for v in adj[u]:
            if v in pd_of:
                edges_in_A.append((ui, pd_of[v]))
        if u in exits:
            edges_in_A.append((ui, 0))  # implicit edge to END, never makes control dep

    targets_set = set(targets)
    queue = []
    in_queue = [False] * Npd

    for t in targets_set:
        if t in pd_of:
            idx = pd_of[t]
            if not in_queue[idx]:
                in_queue[idx] = True
                queue.append(idx)

    head = 0
    while head < len(queue):
        y = queue[head]
        head += 1

        for x, s in edges_in_A:
            # y must post-dominate s
            if not is_ancestor(y, s):
                continue
            # y must not strictly post-dominate x
            if x != y and is_ancestor(y, x):
                continue
            if not in_queue[x]:
                in_queue[x] = True
                queue.append(x)

    # ---------- result ----------
    C_nodes = sorted(num_to_pd[i] for i in range(Npd) if in_queue[i])
    # pd index 0 is END, not a real node
    C_nodes = [x for x in C_nodes if x != 0]
    targets_not_in_A = sorted(t for t in targets_set if t not in pd_of)
    return (C_nodes, targets_not_in_A)

