    rev_adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        rev_adj[v].append(u)

    # reachable nodes
    reachable = set()
    q = deque([entry])
    reachable.add(entry)
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in reachable:
                reachable.add(v)
                q.append(v)

    reachable_blocks = {u: blocks[u] for u in reachable if u in blocks}

    # predecessors among reachable nodes
    pred = [[] for _ in range(n)]
    for u in reachable:
        for v in adj[u]:
            if v in reachable:
                pred[v].append(u)

