    dfn = [-1] * n
    vertex = []          # vertex[i] = node with DFS number i
    parent = [-1] * n

    dfn[entry] = 0
    vertex.append(entry)
    stack = [(entry, 0)]
    while stack:
        u, idx = stack[-1]
        if idx < len(adj[u]):
            v = adj[u][idx]
            stack[-1] = (u, idx + 1)
            if dfn[v] == -1:
                dfn[v] = len(vertex)
                parent[v] = u
                vertex.append(v)
                stack.append((v, 0))
        else:
