        K_x = set()

        # U(x): nodes with an upward-exposed use of x
        U_x = set()

        for node, instrs in reachable_blocks.items():
            seen_def = False
            for op, name in instrs:
                if name != x:
                    continue
                if op in ('def', 'upd'):
                    K_x.add(node)
                if op in ('use', 'upd') and not seen_def:
                    U_x.add(node)
                if op in ('def', 'upd'):
                    seen_def = True

        D_x.update(K_x)

        # P(x): closure of D(x) under dominance frontiers
        P_x = set(D_x)
        q = deque(D_x)
        while q:
            u = q.popleft()
            for v in df[u]:
                if v not in P_x:
                    P_x.add(v)
                    q.append(v)

        # live-in via backward propagation from upward-exposed uses
        live = set(U_x)
        q = deque(U_x)
        while q:
            u = q.popleft()
            for v in rev_adj[u]:
                if v not in reachable:
                    continue
                if v not in live and v not in K_x:
                    live.add(v)
                    q.append(v)

        # phi needed at P(x) ∩ live-in
        phi_nodes = P_x & live
        if phi_nodes:
            for node in phi_nodes:
                phi_by_node.setdefault(node, []).append(x)

    # ---------- output ----------
    result = []
    for node in sorted(phi_by_node.keys()):
        result.append((node, sorted(phi_by_node[node])))
    return result

