        carry = 1
        for pos in range(len(keep_list) - 1, -1, -1):
            v = int(keep_list[pos]) + carry
            if v == 10:
                keep_list[pos] = '0'
                carry = 1
            else:
                keep_list[pos] = str(v)
                carry = 0
                break
        if carry:
            keep_list = ['1'] + ['0'] * len(keep_list)
            base_exp += 1
        keep = ''.join(keep_list)

    # Range check
    if base_exp < -999999999 or base_exp > 999999999:
