def format_sigfigs(s, sig, mode):
    # ---- validate sig ----
    if not isinstance(sig, int) or isinstance(sig, bool) or not (1 <= sig <= 2000):
        raise ValueError("sig must be an int in 1..2000")

    # ---- validate mode ----
    valid_modes = {
        "nearest_even", "nearest_away", "nearest_zero",
        "toward_zero", "away_zero", "toward_neg", "toward_pos",
        "zero_five",
    }
    if not isinstance(mode, str) or mode not in valid_modes:
        raise ValueError("invalid mode")

    # ---- validate s ----
    if not isinstance(s, str) or len(s) > 100000:
        raise ValueError("s must be a string of length <= 100000")
    if len(s) == 0:
        raise ValueError("s must not be empty")

    # ---- parse leading sign ----
    sign_char = "+"
    i = 0
    if s[0] in "+-":
        sign_char = s[0]
        i = 1

    # ---- split mantissa / exponent ----
    e_pos = -1
    for j in range(i, len(s)):
        if s[j] in "eE":
            e_pos = j
            break

    if e_pos != -1:
        mant_str = s[i:e_pos]
        exp_str = s[e_pos + 1:]
    else:
        mant_str = s[i:]
        exp_str = "0"

    # ---- validate mantissa ----
    if not mant_str:
        raise ValueError("missing mantissa")

    dot_count = mant_str.count(".")
    if dot_count > 1:
        raise ValueError("too many decimal points")

    if dot_count == 1:
        int_part, frac_part = mant_str.split(".", 1)
    else:
        int_part, frac_part = mant_str, ""

    if not int_part and not frac_part:
        raise ValueError("mantissa must contain at least one digit")

    digits = int_part + frac_part
    n_frac = len(frac_part)

    for ch in digits:
        if not ("0" <= ch <= "9"):
            raise ValueError("invalid character in mantissa")

    # ---- validate exponent ----
    if not exp_str:
        raise ValueError("missing exponent digits")

    exp_sign_char = "+"
    k = 0
    if exp_str[0] in "+-":
        exp_sign_char = exp_str[0]
        k = 1

    exp_digits = exp_str[k:]
    if not exp_digits or len(exp_digits) > 10:
        raise ValueError("invalid exponent")
    for ch in exp_digits:
        if not ("0" <= ch <= "9"):
            raise ValueError("invalid character in exponent")

    exp_val = int(exp_digits)
    if exp_sign_char == "-":
        exp_val = -exp_val

    # ---- find first significant digit ----
    first_nz = None
    for idx, d in enumerate(digits):
        if d != "0":
