    # ---- zero value ----
    if first_nz is None:
        if sig > 1:
            mant_out = "0." + "0" * (sig - 1)
        else:
            mant_out = "0"
        return mant_out + "e+00"

    # ---- exponent of first significant digit ----
    base_exp = exp_val - n_frac + (len(digits) - 1 - first_nz)

    # ---- extract kept and dropped digits ----
    start = first_nz
    end = start + sig

    if end <= len(digits):
        keep = digits[start:end]
        drop = digits[end:]
    else:
        keep = digits[start:]
        drop = ""
        if len(keep) < sig:
            keep = keep + "0" * (sig - len(keep))

    # ---- rounding decision ----
    # dropped_nonzero: True if any dropped digit is non-zero
    # cmp_half: -1 = below half, 0 = exactly half, 1 = above half
    dropped_nonzero = False
    cmp_half = -1

    if drop:
        for ch in drop:
            if ch != "0":
                dropped_nonzero = True
                break

        first_drop = drop[0]
        if first_drop < "5":
            cmp_half = -1
        elif first_drop > "5":
            cmp_half = 1
        else:  # first_drop == "5"
            rest_zero = True
            for ch in drop[1:]:
                if ch != "0":
                    rest_zero = False
                    break
            if rest_zero:
                cmp_half = 0
            else:
                cmp_half = 1

    do_round_up = False

    if mode == "toward_zero":
        do_round_up = False

    elif mode == "away_zero":
        do_round_up = dropped_nonzero

    elif mode == "toward_neg":
