        if cmp_half > 0:
            do_round_up = True
        elif cmp_half == 0:
            do_round_up = (int(keep[-1]) % 2 == 1)
        else:
            do_round_up = False

    elif mode == "nearest_away":
        do_round_up = dropped_nonzero and cmp_half >= 0

    elif mode == "nearest_zero":
        do_round_up = cmp_half > 0

    elif mode == "zero_five":
        do_round_up = dropped_nonzero and keep[-1] in "05"

    # ---- apply rounding ----
    if do_round_up:
        keep_list = list(keep)
        carry = 1
        for pos in range(len(keep_list) - 1, -1, -1):
            v = int(keep_list[pos]) + carry
            if v == 10:
                keep_list[pos] = "0"
