            else:
                keep_list[pos] = str(v)
                carry = 0
                break

        if carry:
            keep_list = ["1"] + ["0"] * len(keep_list)
            base_exp += 1

        keep = "".join(keep_list)
        if len(keep) > sig:
            keep = keep[:sig]

    # ---- range check ----
    if base_exp < -999999999 or base_exp > 999999999:
        raise ValueError("exponent out of range")

    # ---- format output ----
    if sig > 1:
        mant_out = keep[0] + "." + keep[1:]
    else:
        mant_out = keep[0]

    sign_out = "-" if sign_char == "-" else ""

    exp_sign_out = "+" if base_exp >= 0 else "-"
    exp_digits_out = f"{abs(base_exp):02d}"

    return f"{sign_out}{mant_out}e{exp_sign_out}{exp_digits_out}"

import re

def snap_to_step(x: str, step: str, mode: str) -> str:
    if not isinstance(x, str) or not isinstance(step, str) or not isinstance(mode, str):
        raise ValueError("Inputs must be strings")

    if len(x) > 4000 or len(step) > 4000:
        raise ValueError("Input length exceeds 4000 characters")

    valid_modes = {"floor", "ceil", "outward", "inward",
                   "tie_even", "tie_odd", "tie_away", "tie_zero"}
    if mode not in valid_modes:
        raise ValueError("Invalid mode")

    pat = re.compile(r'^([+-])?(\d+\.?\d*|\.\d+)([eE]([+-]?\d{1,10}))?$')

    def parse(s):
        m = pat.match(s)
        if not m:
            raise ValueError("Invalid decimal format")
        sign_str = m.group(1)
        num_part = m.group(2)
        exp_part = m.group(4)

        if '.' in num_part:
            ip, fp = num_part.split('.', 1)
        else:
            ip, fp = num_part, ""

        digits = ip + fp
        M = int(digits)
        frac_len = len(fp)
        exp_val = int(exp_part) if exp_part else 0
        E = exp_val - frac_len
        sign = 1 if (sign_str is None or sign_str == '+') else -1
        return sign, M, E

    sx, Mx, Ex = parse(x)
    ss, Ms0, Es0 = parse(step)

    if ss != 1 or Ms0 == 0:
        raise ValueError("Step must be strictly greater than zero")

    # Canonicalize step: step = Ms * 10 ** Es, with Ms not divisible by 10.
    Ms = Ms0
    Es = Es0
    while Ms % 10 == 0:
        Ms //= 10
        Es += 1

    d = max(0, -Es)
    if d >= 3000:
        raise ValueError("Output exceeds 3000 digit limit")

    # x = 0 is always exactly a multiple.
    if Mx == 0:
        if d == 0:
            return "0"
        return "0." + "0" * d

    diff = Ex - Es

    # Compute q_abs = floor(|x| / step) and the remainder comparison.
    # rem_cmp: -1 means 2*remainder < step; 0 means equal; 1 means greater.
    if diff >= 0:
        # |x| / step = (Mx * 10^diff) / Ms
        # If diff is huge, the quotient is certainly nonzero and too large.
        if diff > 4000:
            raise ValueError("Output exceeds 3000 digit limit")

        num = Mx * (10 ** diff)
        q_abs, rem = divmod(num, Ms)
        if rem == 0:
            rem_cmp = 0
        else:
            lhs = 2 * rem
            if lhs < Ms:
                rem_cmp = -1
            elif lhs > Ms:
                rem_cmp = 1
            else:
                rem_cmp = 0
    else:
        # |x| / step = Mx / (Ms * 10^(-diff))
        neg = -diff
        if neg > 4000:
            q_abs = 0
            # Compare Mx * 10^Ex with step/2 = Ms * 10^Es / 2.
            # Multiply both sides by 2 * 10^(-Ex) maybe; use exponents.
            # x_abs < step, so compare 2*x_abs with step.
            # 2 * Mx * 10^Ex  vs  Ms * 10^Es
            # Divide by 10^Es: 2 * Mx * 10^(Ex-Es) vs Ms
            # Here Ex-Es = diff is negative.
            # Use 2*Mx vs Ms * 10^(-diff)
            # 10^(-diff) is huge; x is tiny, so 2*x < step unless Ms is tiny.
            # Ms is not divisible by 10, but can be 1.
            # Need exact comparison.
            # Compare 2*Mx * 10^Ex with Ms * 10^Es.
            # Shift by -diff: compare 2*Mx with Ms * 10^(-diff)
            # Since -diff > 4000 and Ms has at most 4000 digits,
            # Ms * 10^(-diff) is enormous; 2*Mx < 10^4001.
            # So 2*x_abs < step always.
            rem_cmp = -1
        else:
            den = Ms * (10 ** neg)
            num = Mx
            q_abs = num // den
            rem = num % den
            if rem == 0:
                rem_cmp = 0
            else:
                # 2*rem < den ?
                lhs = 2 * rem
                if lhs < den:
                    rem_cmp = -1
                elif lhs > den:
                    rem_cmp = 1
                else:
                    rem_cmp = 0

    # Decide k.
    if rem_cmp == 0:
        k = q_abs if sx > 0 else -q_abs
    else:
        x_pos = (sx == 1)
        if x_pos:
            lower = q_abs
            upper = q_abs + 1
        else:
            lower = -q_abs - 1
            upper = -q_abs

        if mode == "floor":
            k = lower
        elif mode == "ceil":
            k = upper
        elif mode == "outward":
            k = upper if x_pos else lower
        elif mode == "inward":
            k = lower if x_pos else upper
        else:
            # Tie modes: choose nearer multiple; on exact tie use mode rule.
            if rem_cmp < 0:
                k = lower
            elif rem_cmp > 0:
                k = upper
            else:
                if mode == "tie_even":
                    k = lower if lower % 2 == 0 else upper
                elif mode == "tie_odd":
                    k = lower if lower % 2 != 0 else upper
                elif mode == "tie_away":
                    k = upper if x_pos else lower
                else:  # tie_zero
                    k = lower if x_pos else upper

    if k == 0:
        if d == 0:
            return "0"
        return "0." + "0" * d

    # Compute |k| * step = |k| * Ms * 10^Es.
    # Es may be positive (extra integer zeros) or negative (fractional digits).
    mag = abs(k) * Ms

    # Check output length before materializing huge powers.
    if Es >= 0:
        # mag * 10^Es has len(str(mag)) + Es digits, unless mag == 0.
        total_digits = len(str(mag)) + Es
        if total_digits > 3000:
            raise ValueError("Output exceeds 3000 digit limit")
        s = str(mag) + "0" * Es
        if d == 0:
            res = s
        else:
            # Es >= 0 and d = 0 always here, because d = max(0,-Es).
            # This branch is unreachable; keep for safety.
            res = s
    else:
        # Es < 0, d = -Es.
        # mag * 10^Es = mag / 10^d
        s = str(mag)
        if len(s) <= d:
            res = "0." + "0" * (d - len(s)) + s
        else:
            p = len(s) - d
