        s = len(str(abs(coeff)))

    # Compute output digit count and reject if > 3000.
    if e >= 0:
        out_digits = s + e
    else:
        dd = -e
        if s <= dd:
            out_digits = dd + 1
        else:
            out_digits = s

    if out_digits > 3000:
        raise ValueError("Output exceeds 3000 digit limit")

    # Format the result.
    abs_coeff = abs(coeff)

    if e >= 0:
        # Append e zeros.
        int_part = str(abs_coeff) + "0" * e
        if k < 0:
            return "-" + int_part
        return int_part
    else:
        dd = -e
        s_coeff = str(abs_coeff)
        if len(s_coeff) <= dd:
            frac_part = "0" * (dd - len(s_coeff)) + s_coeff
            res = "0." + frac_part
        else:
            cut = len(s_coeff) - dd
            res = s_coeff[:cut] + "." + s_coeff[cut:]
        if k < 0:
            res = "-" + res
        return res

import re

def snap_to_step(x: str, step: str, mode: str) -> str:
    if not isinstance(x, str) or not isinstance(step, str) or not isinstance(mode, str):
        raise ValueError("Inputs must be strings")
    if len(x) > 4000 or len(step) > 4000:
        raise ValueError("Input length exceeds 4000 characters")

    valid_modes = {
        "floor", "ceil", "outward", "inward",
        "tie_even", "tie_odd", "tie_away", "tie_zero"
    }
    if mode not in valid_modes:
        raise ValueError("Invalid mode")

    pat = re.compile(r'^([+-])?(\d+\.?\d*|\.\d+)([eE]([+-]?\d{1,10}))?$')

    def parse(s):
        m = pat.match(s)
        if not m:
            raise ValueError("Invalid decimal format")
        sign_str = m.group(1)
        num_part = m.group(2)
        exp_part = m.group(4)

        if '.' in num_part:
            ip, fp = num_part.split('.', 1)
        else:
            ip, fp = num_part, ""

        digits = ip + fp
        if not digits:
            raise ValueError("Invalid decimal format")

        sign = -1 if sign_str == '-' else 1
        val = int(digits)
        frac_len = len(fp)
        exp_val = int(exp_part) if exp_part else 0
        exp = exp_val - frac_len
        return sign, val, exp

    sx, N, Ex = parse(x)
    ss, Ms, Es = parse(step)

    if ss != 1 or Ms == 0:
        raise ValueError("Step must be strictly greater than zero")

    # Canonicalize step: m * 10**e, m not divisible by 10.
    while Ms % 10 == 0:
        Ms //= 10
        Es += 1

    m = Ms
    e = Es
    d = max(0, -e)

    # The fractional part alone already forces too many output digits.
    if d >= 3000:
        raise ValueError("Output exceeds 3000 digit limit")

    # Zero is always a multiple.
    if N == 0:
        if d == 0:
            return "0"
        return "0." + "0" * d

    def compare_2r_with_den(r, den_m, L):
        """Compare 2*r with den_m * 10**L.  L >= 0."""
        left = 2 * r
        len_left = len(str(left))
        len_right = len(str(den_m)) + L
        if len_left < len_right:
            return -1
        if len_left > len_right:
            return 1
        # Same digit length: L is small enough to construct safely.
        right = den_m * (10 ** L)
        if left < right:
            return -1
        if left > right:
            return 1
        return 0

    D = Ex - e

    # Compute floor(|x| / step) and the tie comparison.
    if D >= 0:
        # |x| / step = N * 10**D / m
        lenN = len(str(N))
        lenM = len(str(m))

        # Upper bound for quotient digits.  If this is > 3000, quotient is too big.
        if lenN + D - lenM + 1 > 3000:
            raise ValueError("Output exceeds 3000 digit limit")

        num = N * (10 ** D)
        q_abs, r = divmod(num, m)
        r_is_zero = (r == 0)
        if r_is_zero:
            cmp_half = 0
        else:
            cmp_half = compare_2r_with_den(r, m, 0)
    else:
        L = -D
        lenN = len(str(N))
        lenDen = len(str(m)) + L

        if lenDen > lenN:
            # Denominator is definitely larger: quotient is 0.
            q_abs = 0
            r = N
            r_is_zero = False
            cmp_half = compare_2r_with_den(r, m, L)
        elif lenDen == lenN:
            # Same digit length; denominator is manageable.
            den = m * (10 ** L)
            if N < den:
                q_abs = 0
                r = N
                r_is_zero = False
                cmp_half = compare_2r_with_den(r, m, L)
            else:
                q_abs, r = divmod(N, den)
                r_is_zero = (r == 0)
                if r_is_zero:
                    cmp_half = 0
                else:
                    cmp_half = compare_2r_with_den(r, m, L)
        else:
            # Denominator has fewer digits; construct it and divide.
            den = m * (10 ** L)
            q_abs, r = divmod(N, den)
            r_is_zero = (r == 0)
            if r_is_zero:
                cmp_half = 0
            else:
                cmp_half = compare_2r_with_den(r, m, L)

    # Signed floor quotient.
    if sx == 1:
        q = q_abs
        exact = r_is_zero
    else:
        if r_is_zero:
            q = -q_abs
            exact = True
        else:
            q = -q_abs - 1
            exact = False

    # Choose k.
    if exact:
        k = q
    else:
        if sx == 1:
            if mode == "floor":
                k = q
            elif mode == "ceil":
                k = q + 1
            elif mode == "outward":
                k = q + 1
            elif mode == "inward":
                k = q
            else:  # tie modes
                if cmp_half < 0:
                    k = q
                elif cmp_half > 0:
                    k = q + 1
                else:
                    if mode == "tie_even":
                        k = q if q % 2 == 0 else q + 1
                    elif mode == "tie_odd":
                        k = q if q % 2 != 0 else q + 1
                    elif mode == "tie_away":
                        k = q + 1
                    else:  # tie_zero
                        k = q
        else:
            if mode == "floor":
                k = q
            elif mode == "ceil":
                k = q + 1
            elif mode == "outward":
                k = q
            elif mode == "inward":
                k = q + 1
            else:  # tie modes
                if cmp_half < 0:
                    k = q
                elif cmp_half > 0:
                    k = q + 1
                else:
                    if mode == "tie_even":
                        k = q if q % 2 == 0 else q + 1
                    elif mode == "tie_odd":
                        k = q if q % 2 != 0 else q + 1
                    elif mode == "tie_away":
                        k = q
                    else:  # tie_zero
                        k = q + 1

    # Format k * m * 10**e.
    if k == 0:
        if d == 0:
            return "0"
        return "0." + "0" * d

    coeff = k * m
    abs_coeff = abs(coeff)
    len_coeff = len(str(abs_coeff))

    if e >= 0:
        out_digits = len_coeff + e
        if out_digits > 3000:
            raise ValueError("Output exceeds 3000 digit limit")
        int_part = str(abs_coeff) + "0" * e
        return ("-" + int_part) if k < 0 else int_part

    dd = -e
    if len_coeff <= dd:
        out_digits = dd + 1
        if out_digits > 3000:
            raise ValueError("Output exceeds 3000 digit limit")
        frac_part = "0" * (dd - len_coeff) + str(abs_coeff)
        res = "0." + frac_part
    else:
        out_digits = len_coeff
        if out_digits > 3000:
            raise ValueError("Output exceeds 3000 digit limit")
        s_coeff = str(abs_coeff)
        cut = len_coeff - dd
        res = s_coeff[:cut] + "." + s_coeff[cut:]

    return ("-" + res) if k < 0 else res
